     clicks   presses on mouse or trackpad (a double-click is two); keystrokes don't count
     tools    every app, site or window the task made you touch, in the order you touched them
     log      optional: the moment of every click in the median run, in seconds. With it, the counters tick exactly
              when the real clicks happened; without it they follow the films, then land on the measured total.

   The placeholders below are NOT measurements. The source line says so until you replace it. */
export default {
  old: {
    time: 214.6,                                    // placeholder: replace with your measured median
    clicks: 58,                                     // placeholder
    tools: ['Dashboard', 'Spreadsheet', 'Email'],   // placeholder
    log: null,
  },
  new: {
    time: null,        // null: the product film's last click is the finish (fine once the film is your measured run)
    clicks: null,      // null: the clicks the product film draws
    tools: null,       // null: just the product (its name from the page)
    log: null,
  },
  fastForward: 6,      // wall-clock seconds the rest of the old way takes once the product is done
  beat: 1.4,           // seconds both lanes hold after the product finishes, before the fast-forward
  lead: 'time',        // the ending's big number: 'time' (time back) or 'clicks' (fewer clicks)
  source: 'Placeholder numbers, not a measurement. Replace them with the median of five timed runs of each way: same task, same person, same machine.',

  // the how strip: the product's three key moves, each a frozen moment of the product film.
  // at: a hook the film clicks ('@run') and `after` seconds past that click, or a time in seconds.
  how: [
    { at: '@report', after: -.05, title: 'It’s already <em>set up</em>', line: 'Who it goes to, what’s in it and when: saved once, there every week.' },
    { at: '@run', after: 2.2, title: 'It pulls the <em>numbers</em>', line: 'No copying between tabs. One press fetches every figure.' },
    { at: '@send', after: .6, title: 'It sends <em>itself</em>', line: 'Straight to the people who read it, in the place they read it.' },
  ],
};

// demo/versus: the same task, two ways, racing. Two tours on the engine's manual driver, one wall clock.
//
//   wall clock  0 ─ lead ─ both films play at real speed ─ product done ─ beat ─ fast-forward ─ old way done
//   clocks      race.js decides them: real time until the product is done, then the old way's clock runs through
//               to its measured time while its film plays out its remaining steps (labelled Fast-forward ×n)
//   counters    race.js `log` if given; otherwise the clicks each film draws, landing on the measured totals
//
// The page: the race is the first screen (it starts when it's on screen, or with Start both), then the score,
// the how strip and the time it gives back. ?record&ratio=16:9|1:1|9:16 plays the race, the score, the how
// strip and the ending as one recording; ?t=9 freezes the race (with ?record: the recording) at 9 s.
import { Tour, recordStage, include } from '../tour/tour.js';
import scripts from './script.js';
import race from './race.js';

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const sm = (t) => t * t * t * (t * (t * 6 - 15) + 10);
const io = (t) => (t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const dio = (t) => (t < .5 ? 12 * t * t : 3 * Math.pow(-2 * t + 2, 2));      // io's slope, for the ×n badge
const clock = (s) => { const d = Math.floor(Math.max(0, s) * 10 + 1e-6), m = Math.floor(d / 600), r = d % 600; return `${m}:${String(Math.floor(r / 10)).padStart(2, '0')}.${r % 10}`; };
const span = (s) => { s = Math.round(s); const m = Math.floor(s / 60), r = s % 60; return m ? `${m} min${r ? ` ${r} s` : ''}` : `${r} s`; };
const LEAD = .9;          // a beat at 0:00.0 before the start
const SETTLE = 1.6;       // held after the old way finishes
const SC = { score: 6.2, how: 7, end: 5 };   // ?record: seconds per scene after the race

// harvested screens (<div data-tour-include="…">) load first, then the format starts
export default function init(root) {
  let stop = null, dead = false;
  include(root).then(() => { if (!dead) stop = boot(root); });
  return () => { dead = true; stop?.(); };
}

function boot(root) {
  const q = new URLSearchParams(location.search), rec = q.has('record');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const fixT = q.get('t') != null ? +q.get('t') : null;
  const lanes = { old: root.querySelector('[data-lane="old"]'), new: root.querySelector('[data-lane="new"]') };
  const films = { old: lanes.old.querySelector('.vs-film'), new: lanes.new.querySelector('.vs-film') };
  const name = lanes.new.querySelector('.vs-label em')?.textContent.trim() || 'Product';
  const productWin = films.new.querySelector('[data-tour-window]').cloneNode(true);   // for the how strip, before the engine touches it
  let alive = true, raf = 0, t0 = 0, playing = false, started = false, startT = 0;
  const off = [];
  const on = (el, ev, fn, o) => { el.addEventListener(ev, fn, o); off.push(() => el.removeEventListener(ev, fn, o)); };

  const box = rec ? recordStage(root, q) : null;
  const shape = () => {     // stacked lanes on phones, portrait screens, 1:1 and 9:16
    const w = box ? box.w : innerWidth, h = box ? box.h : innerHeight;
    root.classList.toggle('is-stacked', w / h < 1.2 || (!box && w < 900));
    root.classList.toggle('is-tall', w / h < .8);
    root.style.setProperty('--su', (box ? Math.min(w, h) : Math.min(w, h * 1.25)) / 100 + 'px');
  };
  shape(); on(window, 'resize', shape);

  const opt = { driver: 'manual', record: 'page', captions: 'off' };
  const T = { old: new Tour(films.old, scripts.old, opt), new: new Tour(films.new, scripts.product, opt) };

  // the clicks a film draws up to t (a double-click is two)
  const presses = (tour) => tour.track.filter((g) => g.press && g.kind !== 'swipe').flatMap((g) => (g.kind === 'drag' || g.kind === 'longpress' ? [g.press[0][0]] : g.press.map((p) => p[0])));
  const P = { old: presses(T.old), new: presses(T.new) };
  const upTo = (list, t) => { let n = 0; for (const x of list) if (x <= t) n++; return n; };

  // the race, worked out once
  const lastAct = T.new.track.reduce((m, g) => Math.max(m, g.act ?? g.end ?? 0), 0);
  const R = {
    newT: race.new.time ?? +(lastAct + .25).toFixed(1),
    oldT: race.old.time,
    oldEnd: T.old.outroAt,
  };
  R.newClicks = race.new.clicks ?? upTo(P.new, R.newT);
  R.oldClicks = race.old.clicks ?? P.old.length;
  R.F0 = R.newT + (race.beat ?? 1.4);
  R.FF = R.oldT > R.F0 + 1 ? (race.fastForward ?? 6) : 0;
  R.end = LEAD + R.F0 + R.FF + SETTLE;
  R.oldDrawn = upTo(P.old, R.oldEnd);
  R.tools = { old: race.old.tools || [], new: race.new.tools || [name] };

  // the whole race as a function of the wall clock w
  const at = (w) => {
    const u = Math.max(0, w - LEAD);
    let r, of, p = 0, rate = 1;
    if (u <= R.F0 || !R.FF) { r = Math.min(u, R.FF ? u : R.oldT); of = Math.min(u, R.oldEnd); }
    else { const x = cl((u - R.F0) / R.FF); p = io(x); r = R.F0 + (R.oldT - R.F0) * p; of = R.F0 + (R.oldEnd - R.F0) * p; rate = Math.max(1, (R.oldT - R.F0) / R.FF * dio(x)); }
    const ff = R.FF && u > R.F0 && u < R.F0 + R.FF;
    const oldClock = Math.min(r, R.oldT), newClock = Math.min(u, R.newT);
    const oldClicks = race.old.log ? upTo(race.old.log, oldClock) : u >= R.F0 + R.FF && u > R.F0 ? R.oldClicks
      : Math.min(R.oldClicks, upTo(P.old, of) + Math.round(Math.max(0, R.oldClicks - R.oldDrawn) * p));
    const newClicks = race.new.log ? upTo(race.new.log, newClock) : u >= R.newT ? R.newClicks : Math.min(R.newClicks, upTo(P.new, u));
    return { u, of, nf: u, oldClock, newClock, oldClicks, newClicks, ff, rate, p, oldDone: oldClock >= R.oldT - 1e-6, newDone: u >= R.newT };
  };

  const els = (lane) => ({ time: lane.querySelector('.vs-time'), n: lane.querySelector('.vs-n'), unit: lane.querySelector('.vs-unit'), rate: lane.querySelector('.vs-rate') });
  const E = { old: els(lanes.old), new: els(lanes.new) };
  const put = (el, v) => { if (el && el.textContent !== v) el.textContent = v; };
  let lastW = -1;
  function drawRace(w) {
    if (w === lastW) return; lastW = w;
    const s = at(w);
    T.old.render(s.of); T.new.render(s.nf);
    put(E.old.time, clock(s.oldClock)); put(E.new.time, clock(s.newClock));
    put(E.old.n, String(s.oldClicks)); put(E.new.n, String(s.newClicks));
    put(E.old.unit, s.oldClicks === 1 ? 'click' : 'clicks'); put(E.new.unit, s.newClicks === 1 ? 'click' : 'clicks');
    put(E.old.rate, '×' + Math.round(s.rate));
    lanes.old.classList.toggle('is-ff', s.ff); lanes.old.classList.toggle('is-done', s.oldDone && w > LEAD);
    lanes.new.classList.toggle('is-done', s.newDone);
    lanes.new.style.setProperty('--done', cl((s.u - R.newT) / .5).toFixed(3));
    root.classList.toggle('is-running', playing && w > 0 && w < R.end); root.classList.toggle('is-over', w >= R.end - SETTLE + .2);
  }

  // ── the score, the how strip and the ending, filled from race.js ──
  const rows = {
    time: { old: R.oldT, new: R.newT, f: clock, x: () => `${(R.oldT / R.newT).toFixed(R.oldT / R.newT >= 10 ? 0 : 1)}× faster` },
    clicks: { old: R.oldClicks, new: R.newClicks, f: String, x: () => `${R.oldClicks - R.newClicks} fewer` },
    tools: { old: R.tools.old.length, new: R.tools.new.length, f: String, x: () => (R.tools.new.length === 1 ? `One instead of ${R.tools.old.length}` : `${R.tools.old.length - R.tools.new.length} fewer`) },
  };
  root.querySelectorAll('.vs-srow').forEach((row) => {
    const d = rows[row.dataset.k]; if (!d) return;
    const max = Math.max(d.old, d.new) || 1;
    row.querySelectorAll('.vs-sv').forEach((sv) => {
      const k = sv.classList.contains('is-new') ? 'new' : 'old';
      sv.querySelector('.vs-snum').textContent = d.f(d[k]);
      sv.querySelector('.vs-sbar b').style.setProperty('--w', Math.max(.012, d[k] / max).toFixed(4));
      if (row.dataset.k === 'tools') sv.insertAdjacentHTML('beforeend', `<small class="vs-stools">${R.tools[k].join(' · ')}</small>`);
    });
    row.querySelector('[data-x]').textContent = d.x();
  });
  const src = root.querySelector('[data-source]'); if (src) src.textContent = race.source || '';
  const back = root.querySelector('[data-back]');
  if (back) {
    const clicksLead = race.lead === 'clicks';
    back.textContent = clicksLead ? `${R.oldClicks - R.newClicks} fewer clicks` : span(R.oldT - R.newT);
    back.parentElement.classList.toggle('is-clicks', clicksLead);
  }

  // the how strip: the product window, frozen at each key move
  const moves = root.querySelector('.vs-moves'), mtpl = root.querySelector('template.vs-move-tpl');
  const how = [];
  (race.how || []).forEach((m, i) => {
    if (!moves || !mtpl) return;
    const li = mtpl.content.firstElementChild.cloneNode(true);
    li.querySelector('.vs-mn').textContent = String(i + 1).padStart(2, '0');
    li.querySelector('h3').innerHTML = m.title; li.querySelector('.vs-ml').innerHTML = m.line;
    li.querySelector('.tour-rig').append(productWin.cloneNode(true));
    li.style.setProperty('--i', i);
    moves.append(li);
    const tour = new Tour(li.querySelector('.vs-mfilm'), scripts.product, opt);
    let t = +m.at;
    if (typeof m.at === 'string') {
      const el = tour.win.querySelector(m.at.replace(/@([\w-]+)/g, '[data-tour="$1"]'));
      const g = tour.track.find((x) => x.el === el);
      t = (g ? g.act ?? g.end : 0) + (m.after ?? 1);
    }
    tour.render(t, true); how.push({ tour, t });
  });

  // ── record: the race, then the score, the how strip and the ending, as one take ──
  if (rec) {
    const S0 = R.end, S1 = S0 + SC.score, S2 = S1 + SC.how, DUR = S2 + SC.end;
    const scene = (el, a, b) => { const v = Math.min(sm(cl((T_ - a) / .7)), b == null ? 1 : 1 - sm(cl((T_ - b + .35) / .7))); el.style.opacity = v.toFixed(3); el.style.visibility = v < .001 ? 'hidden' : 'visible'; return v; };
    const parts = { race: root.querySelector('.vs-race'), score: root.querySelector('.vs-score'), how: root.querySelector('.vs-how'), end: root.querySelector('.vs-end') };
    const srows = [...root.querySelectorAll('.vs-srow')], mv = [...root.querySelectorAll('.vs-move')];
    let T_ = 0;
    const frame = (t) => {
      T_ = Math.max(0, Math.min(DUR, t));
      drawRace(Math.min(T_, R.end));
      scene(parts.race, -1, S0); scene(parts.score, S0, S1); scene(parts.how, S1, S2); scene(parts.end, S2);
      srows.forEach((r, i) => r.style.setProperty('--g', sm(cl((T_ - S0 - .6 - i * .45) / 1.1)).toFixed(4)));
      mv.forEach((m, i) => m.style.setProperty('--in', sm(cl((T_ - S1 - .4 - i * .5) / .8)).toFixed(4)));
      root.style.setProperty('--end', sm(cl((T_ - S2 - .2) / 1)).toFixed(4));
    };
    window.versus = { seek: (t) => { playing = false; frame(+t); }, duration: DUR, race: R };
    Promise.all([T.old.api.ready, T.new.api.ready]).then(() => {
      if (!alive) return;
      if (fixT != null) return frame(fixT);
      frame(0);
      setTimeout(() => { if (!alive) return; playing = true; const s = performance.now(); const loop = (now) => { if (!alive || !playing) return; const t = (now - s) / 1000; frame(t); if (t < DUR) raf = requestAnimationFrame(loop); }; raf = requestAnimationFrame(loop); }, (+q.get('hold') || 1.2) * 1000);
    });
    return () => { alive = false; cancelAnimationFrame(raf); off.forEach((f) => f()); Object.values(T).forEach((t) => t.destroy()); how.forEach((h) => h.tour.destroy()); };
  }

  // ── the page ──
  const go = root.querySelector('.vs-go'), goLabel = root.querySelector('.vs-go-label'), again = root.querySelector('.vs-again');
  const stop = () => { playing = false; cancelAnimationFrame(raf); };
  const start = () => {
    stop(); clearTimeout(startT); started = true; root.classList.add('is-started');
    t0 = performance.now(); playing = true; lastW = -1;
    const loop = (now) => {
      if (!alive || !playing) return;
      const w = (now - t0) / 1000; drawRace(Math.min(w, R.end));
      if (w < R.end) raf = requestAnimationFrame(loop);
      else { playing = false; if (goLabel) goLabel.textContent = 'Race again'; }
    };
    raf = requestAnimationFrame(loop);
    if (goLabel) goLabel.textContent = 'Racing…';
  };
  if (go) on(go, 'click', start);
  if (again) on(again, 'click', () => { root.querySelector('.vs-race')?.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth' }); start(); });
  const still = fixT != null || reduce;
  Promise.all([T.old.api.ready, T.new.api.ready]).then(() => {
    if (!alive) return;
    drawRace(still ? (fixT ?? R.end) : 0);
    if (still) { root.classList.add('is-still'); if (goLabel && fixT == null) goLabel.textContent = 'Race again'; return; }
    // start by itself once it's on screen, after a breath at 0:00.0
    const io2 = new IntersectionObserver(([e]) => { if (e.isIntersecting && !started) { clearTimeout(startT); startT = setTimeout(() => { if (!started) start(); }, 900); } else if (!e.isIntersecting) clearTimeout(startT); }, { threshold: .55 });
    io2.observe(root.querySelector('.vs-lanes')); off.push(() => io2.disconnect());
  });
  // the score's bars grow when they come into view
  const io3 = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io3.unobserve(e.target); } }), { threshold: .35 });
  root.querySelectorAll('.vs-srow, .vs-move').forEach((el) => io3.observe(el)); off.push(() => io3.disconnect());
  window.versus = { start, seek: (w) => { stop(); drawRace(+w); }, race: R };

  return () => { alive = false; stop(); clearTimeout(startT); off.forEach((f) => f()); Object.values(T).forEach((t) => t.destroy()); how.forEach((h) => h.tour.destroy()); };
}

/* StyleFeatures scaffolds: the shared placeholder kit.
   Every scaffold section links this first. Tokens can be overridden per site in site.json "theme". */
:root{
  --page:#f5f3ef;--page-2:#ece9e3;--ph:#ffffff;--ph-line:#e3dfd7;--ph-mark:#d9d4ca;
  --ink:#191816;--ink-2:#5f5a53;--ink-3:#9c968c;--rule:#d8d3c9;
  --note:#c2643f;--note-bg:#fbf1ea;
  --serif:'Newsreader',Georgia,serif;--sans:'Inter Tight',system-ui,-apple-system,sans-serif;--mono:ui-monospace,'SF Mono',Menlo,monospace;
  --gutter:clamp(16px,3.4vw,48px);--max:1280px;--radius:2px;
  --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box}
html{background:var(--page);-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}
img{display:block;max-width:100%}
.sf-wrap{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}
.sf-sec{padding-block:clamp(72px,12vh,140px)}

/* ── type ───────────────────────────────────────────── */
.sf-eyebrow{margin:0 0 18px;font:500 12px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.sf-h1{margin:0;font:400 clamp(44px,6.4vw,96px)/.98 var(--serif);letter-spacing:-.025em}
.sf-h2{margin:0;font:400 clamp(32px,4vw,58px)/1.02 var(--serif);letter-spacing:-.02em}
.sf-h3{margin:0;font:500 clamp(19px,1.6vw,23px)/1.2 var(--sans);letter-spacing:-.01em}
.sf-lede{margin:0;max-width:34em;font:400 clamp(17px,1.4vw,20px)/1.5 var(--sans);color:var(--ink-2)}
.sf-small{font:400 13px/1.45 var(--sans);color:var(--ink-3)}

/* ── placeholder image: <figure class="ph" style="--r:4/5" data-ph="Image · 4:5" data-hint="What goes here"></figure> */
.ph{position:relative;margin:0;aspect-ratio:var(--r,4/3);background:var(--ph);border-radius:var(--radius);overflow:hidden;
  box-shadow:inset 0 0 0 1px var(--ph-line);min-width:0}
.ph::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px));
  opacity:.55}
.ph::after{content:attr(data-ph) "\A" attr(data-hint);white-space:pre-line;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:max-content;max-width:min(80%,24em);padding:9px 13px;background:var(--ph);text-align:center;
  font:500 11px/1.45 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);border-radius:var(--radius)}
.ph[data-hint]::after{font-size:11px}
.ph.is-bare::after{content:none}
.ph.is-round{border-radius:50%}
.ph.is-tone{--ph:var(--page-2)}              /* a placeholder on a white card */
.ph > *{position:relative;z-index:1}

/* video placeholder: add .ph-video; scaffold.js adds the transport */
.ph-video{--ph:#f7f6f3}
.ph-video::before{opacity:.35}
.ph-video::after{top:auto;bottom:44px;transform:translateX(-50%);max-width:min(86%,26em)}   /* label sits low, clear of the play button */
.ph-play{position:absolute;z-index:2;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border:0;border-radius:50%;
  background:var(--ink);color:var(--page);cursor:pointer;display:grid;place-items:center;transition:transform .4s var(--ease)}
.ph-play:hover{transform:scale(1.06)}
.ph-play[hidden],.ph-bar[hidden]{display:none}
.ph-play svg{width:20px;height:20px}
.ph-play:focus-visible{outline:2px solid var(--note);outline-offset:4px}
.ph-bar{position:absolute;z-index:2;left:16px;right:16px;bottom:14px;display:flex;align-items:center;gap:12px;font:500 11px/1 var(--mono);color:var(--ink-3)}
.ph-track{flex:1;height:2px;background:var(--ph-line);position:relative;overflow:hidden}
.ph-track i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.ph-video.is-playing::before{animation:ph-breathe 3.2s ease-in-out infinite}
@keyframes ph-breathe{50%{opacity:.12}}

/* placeholder copy: <p class="ph-text" style="--n:3"></p>  (n lines, last one short) */
.ph-text{--lh:1.6em;display:block;margin:0;height:calc(var(--n,3) * var(--lh));max-width:32em;
  background:repeating-linear-gradient(to bottom,var(--ph-line) 0 .55em,transparent .55em var(--lh));
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat;
          mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat}
.ph-logo{display:inline-flex;align-items:center;justify-content:center;height:34px;min-width:110px;padding:0 14px;border-radius:var(--radius);
  box-shadow:inset 0 0 0 1px var(--ph-line);background:var(--ph);font:600 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}

/* ── controls ───────────────────────────────────────── */
.sf-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:0;border-radius:var(--radius);background:var(--ink);color:var(--page);
  font:500 14px/1 var(--sans);text-decoration:none;cursor:pointer;transition:background-color .3s ease,color .3s ease,box-shadow .3s ease}
.sf-btn:hover{background:#000}
.sf-btn--ghost{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.sf-btn--ghost:hover{background:var(--ink);color:var(--page)}
.sf-btn--text{padding:6px 0;background:none;color:var(--ink);box-shadow:inset 0 -1px 0 currentColor}
.sf-btn--text:hover{background:none;color:var(--ink-2)}
.sf-btn:focus-visible,.sf-field:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.sf-field{width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--rule);background:transparent;font:400 16px/1.2 var(--sans);color:var(--ink);border-radius:0}
.sf-field::placeholder{color:var(--ink-3)}
.sf-rule{height:0;border:0;border-top:1px solid var(--rule);margin:0}

/* ── notes: what goes here / who it suits. <span class="sf-note">Swap for your logo</span>; html.sf-clean hides them */
.sf-note{display:inline-flex;align-items:center;gap:7px;padding:5px 9px 5px 7px;border-radius:var(--radius);background:var(--note-bg);color:var(--note);
  font:500 11px/1.25 var(--sans);letter-spacing:.01em;vertical-align:middle;white-space:normal;max-width:30em}
.sf-note::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
.sf-note.is-pin{position:absolute;z-index:5}
html.sf-clean .sf-note{display:none!important}

/* ── reveal ─────────────────────────────────────────── */
[data-reveal]{opacity:0;transform:translateY(14px);transition:opacity 1s var(--ease),transform 1.2s var(--ease);transition-delay:calc(var(--i,0) * 80ms)}
[data-reveal].is-in{opacity:1;transform:none}
.no-js [data-reveal]{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-reveal]{opacity:1;transform:none;transition:none}}

/* ── preview spec card (only on preview pages) ───────── */
.sf-spec{position:fixed;z-index:9999;left:14px;bottom:14px;max-width:min(360px,calc(100vw - 28px));padding:14px 16px;border-radius:4px;
  background:rgba(255,255,255,.94);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px var(--ph-line),0 10px 30px -14px rgba(0,0,0,.3);
  font:400 12px/1.45 var(--sans);color:var(--ink-2)}
.sf-spec b{display:block;font:500 14px/1.25 var(--sans);color:var(--ink);margin:6px 0 3px}
.sf-spec .sf-kind{margin-right:6px}
.sf-spec ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.sf-spec li{padding:3px 7px;border-radius:2px;background:var(--page);color:var(--ink-2);font-size:11px}
.sf-spec button{margin-top:10px;padding:0;border:0;background:none;font:500 11px/1 var(--sans);color:var(--ink-3);text-decoration:underline;cursor:pointer}
.sf-spec.is-min p,.sf-spec.is-min ul{display:none}
.sf-thumb .sf-spec{display:none}
@media (max-width:700px){.sf-spec{left:8px;bottom:8px;padding:10px 12px}}
.sf-kind{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 7px;border-radius:2px;font:600 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase}
.sf-kind::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.sf-kind--static{background:#eceae5;color:#6f6a62}
.sf-kind--interactive{background:#fbeee6;color:#b65a35}
.sf-kind--video{background:#1d1c1a;color:#f2efe9}

/* tour.css: the engine's own look. Window chromes, the cursor, ripples, chapter card, caption, key caps,
   the play controls, the auto-play switch and the ?record stage. Shared by every demo film; a template
   restyles it through these tokens rather than editing it:
     --tour-stage  backdrop behind the window        --tour-win-radius  window corners (design px)
     --tour-ring   click ripple colour               --tour-cap-bg / --tour-cap-ink  caption pill
   Sizes on the stage scale with --su (a hundredth of the stage's short side, set by tour.js). */

[data-tour-root]{position:relative;--tour-stage:var(--page-2,#ece9e3);--tour-ring:rgba(25,24,22,.42);--tour-cap-bg:var(--ink,#191816);--tour-cap-ink:var(--page,#f5f3ef);--tour-win-radius:12px}
[data-tour-stage]{position:sticky;top:0;height:100svh;overflow:hidden;background:var(--tour-stage);isolation:isolate;--su:9px}
[data-tour-root].is-play [data-tour-stage],[data-tour-root].is-still [data-tour-stage]{position:relative}
.tour-rig{position:absolute;inset:0}

/* the window: design pixels, scaled by the camera */
[data-tour-window]{position:absolute;left:0;top:0;transform-origin:0 0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:var(--tour-win-radius);background:var(--ph,#fff);
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 40px 90px -40px rgba(25,24,22,.5),0 12px 28px -16px rgba(25,24,22,.28)}
[data-tour-window] > :not(.tour-chrome){flex:1;min-height:0}
.tour-chrome{flex:none;height:40px;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--page,#f5f3ef);border-bottom:1px solid var(--ph-line,#e3dfd7);font:500 12.5px/1 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-lights{display:flex;gap:8px}
.tour-lights i{width:12px;height:12px;border-radius:50%;background:#ec6a5e;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.12)}
.tour-lights i+i{background:#f4bf4f}.tour-lights i+i+i{background:#61c554}
.tour-navs{display:flex;gap:10px}.tour-navs.is-end{margin-left:auto}
.tour-chrome svg{width:15px;height:15px;fill:none;stroke:var(--ink-3,#9c968c);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.tour-url{flex:0 1 420px;margin-left:auto;display:flex;align-items:center;justify-content:center;gap:7px;height:26px;padding:0 14px;border-radius:7px;background:var(--ph,#fff);box-shadow:inset 0 0 0 1px var(--ph-line,#e3dfd7);font-weight:400;color:var(--ink-2,#5f5a53);white-space:nowrap;overflow:hidden}
.tour-url svg{width:12px;height:12px}
.tour-chrome[data-kind=app]{height:38px;justify-content:center;position:relative}
.tour-chrome[data-kind=app] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=phone]{height:46px;justify-content:space-between;padding:0 26px;background:transparent;border:0;font:600 15px/1 var(--sans,system-ui);color:var(--ink,#191816)}
.tour-notch{width:120px;height:32px;border-radius:20px;background:#111}
.tour-status{display:flex;gap:4px}.tour-status i{width:16px;height:10px;border-radius:2px;background:var(--ink,#191816)}
[data-chrome=phone]{--tour-win-radius:54px;box-shadow:0 0 0 10px #111,0 0 0 11px #333,0 40px 90px -30px rgba(25,24,22,.55)}
[data-chrome=none]{--tour-win-radius:8px}
/* terminal: a warm charcoal window (tokens --tour-term-bg, --tour-term-bar, --tour-term-ink, --tour-term-dim) */
[data-chrome=terminal]{background:var(--tour-term-bg,#1d1b18);color:var(--tour-term-ink,#ebe5d9)}
.tour-chrome[data-kind=terminal]{height:38px;justify-content:center;position:relative;background:var(--tour-term-bar,#272420);border-bottom:1px solid rgba(255,255,255,.07);color:var(--tour-term-dim,#a39b8e);font-weight:500}
.tour-chrome[data-kind=terminal] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=terminal] .tour-lights i{box-shadow:inset 0 0 0 .5px rgba(0,0,0,.3)}
/* windows inside the window: any [data-chrome] element in the product gets its own chrome and frame */
[data-tour-window] [data-chrome]{display:flex;flex-direction:column;overflow:hidden;border-radius:var(--tour-win-radius)}
[data-tour-window] [data-chrome] > :not(.tour-chrome){flex:1;min-height:0}

/* cursor and ripples (stage coordinates) */
.tour-cur{position:absolute;left:0;top:0;z-index:8;width:0;height:0;pointer-events:none;opacity:0;transform-origin:0 0}
.tour-cur svg{position:absolute;left:-1px;top:-1px;overflow:visible;filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.35)) drop-shadow(0 3px 6px rgba(0,0,0,.12))}
.tour-cur .tour-arrow path{fill:#141312;stroke:#fff;stroke-width:1.3}
.tour-cur .tour-hand{left:-8px;top:-2px}
.tour-cur .tour-hand path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-cur .tour-beam{left:-5px;top:-12px}
.tour-cur .tour-beam path{stroke:#141312;stroke-width:1.6;paint-order:stroke}
.tour-cur[data-look=light] .tour-arrow path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-ring{position:absolute;left:0;top:0;z-index:7;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;border:2.5px solid var(--tour-ring);background:color-mix(in srgb,var(--tour-ring) 18%,transparent);pointer-events:none;opacity:0}
/* pointer:'touch': a fingertip (44 window px, it zooms with the screen) instead of the arrow; tour.js sets its opacity and size */
.tour-touch{display:none;position:absolute;left:-22px;top:-22px;width:44px;height:44px;border-radius:50%;background:var(--tour-touch,rgba(112,112,120,.36));
  box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.62),0 0 0 1px rgba(20,19,18,.1),0 3px 12px -3px rgba(20,19,18,.32)}
.tour-cur.is-down .tour-touch{background:var(--tour-touch-down,rgba(92,92,100,.48));box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.7),0 0 0 1px rgba(20,19,18,.12),0 1px 5px -1px rgba(20,19,18,.3)}
.is-touch .tour-touch{display:block}
.is-touch .tour-cur svg{display:none!important}
.is-touch .tour-ring{width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid rgba(112,112,120,.55);background:none}
/* more than one pointer (steps with { by: 'agent' }): its own colour (--tour-agent) and a label tag; the person's
   cursor gets a tag too when pointers.main.label is set */
.tour-cur[data-look=agent] .tour-arrow path{fill:var(--tour-agent,#3b4bc8);stroke:#fff;stroke-width:1.4}
.tour-cur[data-look=agent] svg{filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.25)) drop-shadow(0 0 7px color-mix(in srgb,var(--tour-agent,#3b4bc8) 45%,transparent))}
.tour-tag{position:absolute;left:13px;top:21px;display:flex;align-items:center;gap:6px;height:22px;padding:0 8px;border-radius:6px;background:var(--ink,#191816);color:#fff;
  font:600 11.5px/1 var(--sans,system-ui);letter-spacing:.01em;white-space:nowrap;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.tour-tag span{font:500 11px/1 var(--mono,ui-monospace,monospace);opacity:.82}
.tour-tag span[hidden]{display:none}
.tour-cur[data-look=agent] .tour-tag{background:var(--tour-agent,#3b4bc8)}
.tour-ring[data-who]:not([data-who=main]){--tour-ring:var(--tour-agent,#3b4bc8)}

/* chapter card: "02 / 05", a title with one italic word, one line */
.tour-card{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su)*44),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*2);background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;transform:translateY(calc((1 - var(--o,0)) * 10px));pointer-events:none}
.tour-card-n{font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans,system-ui);letter-spacing:.14em;color:var(--ink-3,#9c968c)}
.tour-card h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif,Georgia,serif);letter-spacing:-.018em;color:var(--ink,#191816)}
.tour-card h3 em{font-style:italic}
.tour-card p{margin:0;font:400 max(13.5px,calc(var(--su)*1.7))/1.45 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-card,.tour-cap{transition:translate .55s cubic-bezier(.2,.7,.2,1)}
.tour-card[data-dodge=hide]{opacity:0!important}
.tour-card[data-dodge=off]{display:none}
.tour-card-x{position:absolute;top:calc(var(--su)*.9);right:calc(var(--su)*.9);width:max(26px,calc(var(--su)*2.8));height:max(26px,calc(var(--su)*2.8));display:grid;place-items:center;
  padding:0;border:0;border-radius:50%;background:transparent;color:var(--ink-3,#9c968c);font:400 max(16px,calc(var(--su)*1.9))/1 var(--sans,system-ui);cursor:pointer;pointer-events:auto;opacity:.7}
.tour-card-x:hover{opacity:1;background:var(--ph-line,#e3dfd7);color:var(--ink,#191816)}
.tour-card-x:focus-visible{outline:2px solid var(--tour-ring,#c2643f);outline-offset:2px;opacity:1}
.is-stack .tour-card{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top);padding:calc(var(--su)*2) calc(var(--su)*2.4)}
[data-tour-root].is-play:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 46px)}

/* caption line: burned into recordings, because X autoplays muted */
.tour-cap{position:absolute;z-index:7;left:50%;bottom:calc(var(--su)*4);margin:0;max-width:min(calc(var(--su)*72),calc(100% - 2 * var(--gutter,32px)));width:max-content;
  padding:calc(var(--su)*1.05) calc(var(--su)*1.9);border-radius:calc(var(--su)*.6);background:var(--tour-cap-bg);color:var(--tour-cap-ink);
  font:500 max(14px,calc(var(--su)*2.35))/1.3 var(--sans,system-ui);letter-spacing:-.005em;text-align:center;opacity:0;transform:translate(-50%,calc((1 - var(--o,0)) * 8px));pointer-events:none;text-wrap:balance}
.is-stack .tour-cap{bottom:calc(var(--su)*5)}
.is-stack.is-tall .tour-cap{bottom:auto;top:var(--cap-top)}
[data-tour-root].is-play .tour-cap{bottom:calc(var(--su)*4 + 46px)}

/* key caps */
.tour-keys{position:absolute;z-index:7;display:flex;gap:calc(var(--su)*.6);transform:translate(-50%,calc((1 - var(--o,0)) * 8px));opacity:0;pointer-events:none}
.tour-keys kbd{min-width:calc(var(--su)*5.4);height:calc(var(--su)*5.4);padding:0 calc(var(--su)*1.2);display:grid;place-items:center;border-radius:calc(var(--su)*.9);
  background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 calc(var(--su)*.35) 0 var(--ph-line,#e3dfd7),0 14px 30px -16px rgba(25,24,22,.5);
  font:500 calc(var(--su)*2.4)/1 var(--sans,system-ui);color:var(--ink,#191816)}

/* play driver: one quiet bar */
.tour-ctl{position:absolute;z-index:9;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(620px,calc(100% - 28px));
  padding:7px 14px 7px 7px;border-radius:999px;background:color-mix(in srgb,var(--ph,#fff) 92%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 12px 30px -18px rgba(25,24,22,.5);
  font:500 11.5px/1 var(--mono,ui-monospace,monospace);color:var(--ink-2,#5f5a53)}
.tour-pp{flex:none;width:32px;height:32px;border:0;border-radius:50%;display:grid;place-items:center;background:var(--ink,#191816);color:var(--page,#f5f3ef);cursor:pointer}
.tour-pp svg{width:13px;height:13px;fill:currentColor}
.tour-pp:focus-visible,.tour-scrub input:focus-visible{outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-scrub{position:relative;flex:1;height:20px;display:flex;align-items:center}
.tour-scrub::before{content:"";position:absolute;left:0;right:0;height:2px;background:var(--ph-line,#e3dfd7)}
.tour-scrub::after{content:"";position:absolute;left:0;height:2px;width:calc(var(--v,0) * 100%);background:var(--ink,#191816)}
.tour-scrub i{position:absolute;top:5px;width:1px;height:10px;background:var(--ink-3,#9c968c)}
.tour-scrub input{position:relative;z-index:1;width:100%;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer;height:20px}
.tour-scrub input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink,#191816)}
.tour-scrub input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink,#191816)}
.tour-time{flex:none;min-width:84px;text-align:right}
[data-tour-root]:not(.is-begun) .tour-ctl{opacity:0;pointer-events:none}
.tour-ctl{transition:opacity .4s ease}
.is-stack .tour-time{display:none}

/* scroll driver: the auto-play switch, the only way to take over while it plays itself */
.tour-drift{position:absolute;z-index:9;right:var(--gutter,16px);bottom:16px;display:flex;align-items:center;gap:10px;padding:7px 8px 7px 14px;border-radius:999px;
  background:color-mix(in srgb,var(--ph,#fff) 88%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 10px 26px -14px rgba(25,24,22,.45);
  font:500 12px/1 var(--sans,system-ui);color:var(--ink,#191816);cursor:pointer;user-select:none;transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1)}
.tour-drift input{position:absolute;opacity:0;pointer-events:none}
.tour-drift > i{position:relative;width:34px;height:20px;border-radius:999px;background:var(--ink,#191816);transition:background-color .25s}
.tour-drift > i::after{content:"";position:absolute;top:3px;left:17px;width:14px;height:14px;border-radius:50%;background:var(--page,#f5f3ef);transition:left .3s cubic-bezier(.2,.7,.2,1)}
.tour-drift:has(input:not(:checked)) > i{background:var(--rule,#d8d3c9)}
.tour-drift:has(input:not(:checked)) > i::after{left:3px}
.tour-drift:has(input:focus-visible){outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-drift.is-gone{opacity:0;transform:translateY(8px);pointer-events:none}
.tour-say{position:absolute;right:0;bottom:calc(100% + 10px);width:max-content;max-width:min(260px,calc(100vw - 32px));padding:9px 12px;border-radius:8px;background:var(--ink,#191816);color:var(--page,#f5f3ef);
  font:500 12px/1.35 var(--sans,system-ui);opacity:0;transform:translateY(6px);pointer-events:none;transition:opacity .3s,transform .4s cubic-bezier(.2,.7,.2,1)}
.tour-drift.is-saying .tour-say{opacity:1;transform:none}
.tour-drift.is-saying{box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 0 0 4px color-mix(in srgb,var(--note,#c2643f) 35%,transparent)}

/* ?record: a clean stage of the chosen ratio, centred in the browser window, for Monet Shot to record */
html.tour-record,html.tour-record body{height:100%;overflow:hidden;background:#0e0e0d}
html.tour-record body :not([data-tour-root].is-record,[data-tour-root].is-record *,:has([data-tour-root].is-record)){display:none!important}   /* everything but the film (which may sit inside another section) */
html.tour-record .sf-note,html.tour-record .sf-spec,html.tour-record [data-tour-gate],html.tour-record [data-tour-hide-on-record]{display:none!important}
html.tour-record [data-tour-root].is-record{position:fixed;left:50%;top:50%;width:var(--rw);height:var(--rh)!important;transform:translate(-50%,-50%);z-index:2147483000;cursor:none}
html.tour-record .is-record [data-tour-stage]{position:absolute;inset:0;height:auto}

@media (prefers-reduced-motion:reduce){.tour-drift,.tour-drift *,.tour-say{transition:none}}

@import url("../tour/tour.css");
/* demo/versus: the same task, two ways, racing. The race (the first screen), the score, the how strip, the time
   it gives back. Sizes in the race follow --su (a hundredth of the screen's short side, set by section.js), so
   the page and every ?record ratio lay out the same way. */

.demo-versus{position:relative;background:var(--page);color:var(--ink);--line:var(--ph-line)}
.demo-versus em{font-style:italic}

/* ── the race ── */
.vs-race{position:relative;min-height:100svh;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:max(14px,calc(var(--su)*2.4));
  padding:max(22px,calc(var(--su)*4.4)) var(--gutter) max(14px,calc(var(--su)*2.2))}
.vs-head{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:20px clamp(24px,4vw,64px)}
.vs-head .sf-eyebrow{margin-bottom:max(10px,calc(var(--su)*1.5))}
.vs-task{margin:0;font:400 max(32px,calc(var(--su)*6.2))/.98 var(--serif);letter-spacing:-.024em;text-wrap:balance;max-width:16em}
.vs-head-act{display:flex;flex-direction:column;align-items:flex-end;gap:12px;padding-bottom:.3em}
.vs-head-act .sf-note{max-width:24em}
.vs-go{min-width:9.6em;justify-content:center}
.demo-versus.is-running .vs-go{opacity:.45;pointer-events:none}

.vs-lanes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:max(16px,calc(var(--su)*3.6));min-height:0}
.vs-lane{--meta:max(56px,calc(var(--su)*8.4));position:relative;display:flex;flex-direction:column;justify-content:center;min-width:0;min-height:0;container-type:size}
.vs-lane > .vs-meta{flex:none;height:var(--meta);width:min(100cqw,calc((100cqh - var(--meta)) * 1.5172));align-self:center}
.vs-lane + .vs-lane::before{content:"";position:absolute;left:calc(max(16px,calc(var(--su)*3.6)) / -2);top:0;bottom:0;border-left:1px solid var(--rule)}
.vs-meta{display:grid;grid-template-columns:1fr auto auto;align-items:end;gap:0 max(14px,calc(var(--su)*2.6));padding-bottom:max(10px,calc(var(--su)*1.5));position:relative}
.vs-label{grid-column:1 / -1;margin:0 0 max(6px,calc(var(--su)*.9));font:500 max(11px,calc(var(--su)*1.25))/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.vs-label em{font:italic 400 1.3em/1 var(--serif);letter-spacing:0;text-transform:none;color:var(--ink)}
.vs-clock{grid-row:2;grid-column:1;margin:0;font:300 max(30px,calc(var(--su)*5.4))/.84 var(--sans);letter-spacing:-.035em;font-variant-numeric:tabular-nums;color:var(--ink)}
.vs-clicks{grid-row:2;grid-column:3;margin:0;font:400 max(13px,calc(var(--su)*1.6))/1 var(--sans);color:var(--ink-2);white-space:nowrap}
.vs-clicks b{font:400 max(20px,calc(var(--su)*2.9))/1 var(--sans);font-variant-numeric:tabular-nums;color:var(--ink);letter-spacing:-.02em}
/* fast-forward and done badges */
.vs-ff,.vs-done{grid-row:2;grid-column:2;display:inline-flex;align-items:center;gap:7px;margin:0;padding:max(6px,calc(var(--su)*.8)) max(10px,calc(var(--su)*1.2));border-radius:99px;
  font:500 max(11px,calc(var(--su)*1.2))/1 var(--sans);white-space:nowrap;opacity:0;transform:translateY(4px);transition:opacity .35s var(--ease),transform .45s var(--ease)}
.vs-ff{background:var(--ink);color:var(--page)}
.vs-ff b{font:600 1em/1 var(--sans);font-variant-numeric:tabular-nums;min-width:2.8em}
.vs-ff svg,.vs-done svg{width:1.15em;height:1.15em;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linejoin:round;stroke-linecap:round}
.vs-ff svg{fill:currentColor;stroke:none}
.vs-lane.is-ff .vs-ff{opacity:1;transform:none}
.vs-done{background:var(--note);color:#fff}
.vs-lane.is-done .vs-done{opacity:1;transform:none}
.vs-lane.is-new.is-done .vs-clock{color:var(--note)}
.vs-lane[data-lane="old"].is-done .vs-clock{color:var(--ink-2)}

/* the window: a frame the engine fits the window into, as big as the lane allows at 880 × 580 */
.vs-film{position:relative;align-self:start;justify-self:center;width:min(100cqw,calc((100cqh - var(--meta)) * 1.5172));aspect-ratio:880/580;border-radius:max(6px,calc(var(--su)*.9));
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 30px 70px -36px rgba(25,24,22,.5),0 10px 24px -16px rgba(25,24,22,.26);background:var(--ph)}
.demo-versus .vs-film [data-tour-stage]{position:absolute;inset:0;height:auto;background:transparent;border-radius:inherit}
.vs-frame{position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.vs-film .tour-card,.vs-film .tour-cap{display:none}
.vs-film [data-tour-window]{box-shadow:none}
.vs-lane.is-new .vs-film{box-shadow:0 0 0 calc(var(--done,0) * 2px) var(--note),0 30px 70px -36px rgba(25,24,22,.5),0 10px 24px -16px rgba(25,24,22,.26)}
.vs-film .tour-chrome{background:var(--page)}
.vs-film .tour-keys kbd{min-width:max(30px,calc(var(--su)*4.4));height:max(30px,calc(var(--su)*4.4));font-size:max(14px,calc(var(--su)*2))}

.vs-foot{display:flex;align-items:center;justify-content:space-between;gap:12px 24px;flex-wrap:wrap;margin:0;font:400 max(12px,calc(var(--su)*1.3))/1.4 var(--sans);color:var(--ink-3)}
.vs-again{display:inline-flex;align-items:center;gap:8px;padding:6px 0;border:0;background:none;box-shadow:inset 0 -1px 0 currentColor;font:500 13px/1 var(--sans);color:var(--ink);cursor:pointer;
  opacity:0;pointer-events:none;transition:opacity .4s var(--ease)}
.vs-again svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.demo-versus.is-over .vs-again{opacity:1;pointer-events:auto}
.vs-again:focus-visible{outline:2px solid var(--note);outline-offset:4px}

/* stacked: phones, portrait screens, 1:1 and 9:16. Lanes one above the other; in 1:1 the meta sits beside the window */
.demo-versus.is-stacked .vs-lanes{grid-template-columns:minmax(0,1fr);grid-template-rows:repeat(2,minmax(0,1fr))}
.demo-versus.is-stacked .vs-lane + .vs-lane::before{left:0;right:0;top:calc(max(16px,calc(var(--su)*3.6)) / -2);bottom:auto;border-left:0;border-top:1px solid var(--rule)}
.demo-versus.is-stacked:not(.is-tall) .vs-lane{--meta:0px;flex-direction:row;align-items:center;justify-content:flex-start;gap:calc(var(--su)*3)}
.demo-versus.is-stacked:not(.is-tall) .vs-lane > .vs-meta{height:auto;width:calc(var(--su)*22)}
.demo-versus.is-stacked:not(.is-tall) .vs-meta{grid-template-columns:auto;align-content:center;align-items:start;gap:calc(var(--su)*1.4);padding:0}
.demo-versus.is-stacked:not(.is-tall) .vs-meta > *{grid-row:auto;grid-column:auto;justify-self:start}
.demo-versus.is-stacked:not(.is-tall) .vs-film{align-self:center;width:min(calc(100cqw - var(--su)*25),calc(100cqh * 1.5172))}
.demo-versus.is-stacked .vs-head{grid-template-columns:minmax(0,1fr);gap:14px}
.demo-versus.is-stacked .vs-head-act{align-items:flex-start;flex-direction:row;flex-wrap:wrap}
.demo-versus.is-stacked.is-tall .vs-film{align-self:center}

/* ── the score ── */
.vs-score,.vs-how,.vs-end{padding:clamp(72px,12vh,140px) var(--gutter)}
.vs-score{border-top:1px solid var(--rule)}
.vs-score-in,.vs-how-in,.vs-end-in{max-width:1280px;margin:0 auto}
.vs-rows{display:grid}
.vs-srow{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,2fr) minmax(0,.7fr);grid-template-rows:auto auto;gap:14px clamp(20px,3vw,48px);align-items:center;padding:clamp(22px,3.4vh,34px) 0;border-top:1px solid var(--rule)}
.vs-srow:last-child{border-bottom:1px solid var(--rule)}
.vs-sk{grid-row:1 / span 2;margin:0;font:400 clamp(26px,2.6vw,40px)/1 var(--serif);letter-spacing:-.015em}
.vs-sv{grid-column:2;display:grid;grid-template-columns:8.5em minmax(0,1fr) 6.5em;align-items:center;gap:16px}
.vs-sl{font:500 12px/1.2 var(--sans);letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vs-sv.is-new .vs-sl{color:var(--ink)}
.vs-sbar{position:relative;height:10px;background:var(--page-2);border-radius:1px;overflow:hidden}
.vs-sbar b{position:absolute;inset:0;background:var(--ink-3);transform-origin:left;transform:scaleX(0);transition:transform 1.4s var(--ease)}
.vs-sv.is-new .vs-sbar b{background:var(--note)}
.vs-srow.is-in .vs-sbar b{transform:scaleX(var(--w))}
.vs-sv.is-new .vs-sbar b{transition-delay:.25s}
.vs-snum{font:400 clamp(20px,1.9vw,28px)/1 var(--sans);font-variant-numeric:tabular-nums;letter-spacing:-.02em;text-align:right;white-space:nowrap}
.vs-stools{grid-column:2;margin-top:-8px;font:400 12px/1.3 var(--sans);color:var(--ink-3)}
.vs-sx{grid-column:3;grid-row:1 / span 2;margin:0;font:italic 400 clamp(20px,1.9vw,28px)/1.1 var(--serif);color:var(--note);text-align:right}
.vs-source{margin:22px 0 0;max-width:48em;font:400 13px/1.5 var(--sans);color:var(--ink-3)}
.vs-source::before{content:"Source · ";font-weight:500;color:var(--ink-2)}

/* ── how ── */
.vs-how-h{margin:0 0 clamp(28px,5vh,52px);font:400 clamp(36px,4.2vw,64px)/1 var(--serif);letter-spacing:-.022em}
.vs-moves{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(18px,2.4vw,36px)}
.vs-move{opacity:0;transform:translateY(14px);transition:opacity .9s var(--ease),transform 1.1s var(--ease);transition-delay:calc(var(--i) * 120ms)}
.vs-move.is-in{opacity:1;transform:none}
.vs-mframe{position:relative;aspect-ratio:880/580;border-radius:6px;background:var(--ph);box-shadow:0 0 0 1px rgba(25,24,22,.1),0 22px 50px -30px rgba(25,24,22,.45)}
.vs-mfilm{position:absolute;inset:0;border-radius:inherit}
.demo-versus .vs-mfilm [data-tour-stage]{position:absolute;inset:0;height:auto;background:transparent;border-radius:inherit}
.vs-mfilm .tour-card,.vs-mfilm .tour-cap,.vs-mfilm .tour-keys{display:none}
.vs-mfilm [data-tour-window]{box-shadow:none}
.vs-mfilm .tour-chrome{background:var(--page)}
.vs-mn{margin:20px 0 10px;font:500 12px/1 var(--sans);letter-spacing:.14em;color:var(--ink-3)}
.vs-move h3{margin:0;font:400 clamp(24px,2.1vw,32px)/1.05 var(--serif);letter-spacing:-.015em}
.vs-ml{margin:10px 0 0;max-width:26em;font:400 15px/1.5 var(--sans);color:var(--ink-2)}

/* ── the end: the time it gives back ── */
.vs-end{border-top:1px solid var(--rule);padding-bottom:clamp(56px,9vh,96px)}
.vs-back{margin:0;font:400 clamp(72px,13.5vw,240px)/.86 var(--serif);letter-spacing:-.04em;white-space:nowrap}
.vs-back em{color:var(--note)}
.vs-back.is-clicks em{display:none}
.vs-end-row{display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:24px 40px;margin-top:clamp(36px,7vh,72px);padding-top:24px;border-top:1px solid var(--rule)}
.vs-end-name{margin:0;font:400 clamp(30px,3vw,46px)/1 var(--serif);letter-spacing:-.02em}
.vs-end-act{display:flex;align-items:center;gap:20px;flex-wrap:wrap}
.vs-url-end{font:500 13px/1 var(--mono);color:var(--ink-3)}
.vs-end .sf-note{margin-top:20px}

@media (max-width:860px){
  .vs-stools{grid-column:2 / -1}
  .vs-srow{grid-template-columns:minmax(0,1fr);gap:12px}
  .vs-sk,.vs-sv,.vs-sx{grid-column:1;grid-row:auto}
  .vs-sx{text-align:left}
  .vs-sv{grid-template-columns:6.5em minmax(0,1fr) 5.6em;gap:10px}
  .vs-moves{grid-template-columns:minmax(0,1fr);gap:40px}
  .vs-back{font-size:clamp(52px,16vw,120px);white-space:normal}
}
@media (prefers-reduced-motion:reduce){
  .vs-move,.vs-sbar b,.vs-ff,.vs-done,.vs-again{transition:none}
}

/* ── ?record: one take. The race, then the score, the how strip and the ending cross-fade in the same box ── */
.demo-versus.is-record{overflow:hidden;background:var(--page);cursor:none}
.demo-versus.is-record > .vs-race,.demo-versus.is-record > section,.demo-versus.is-record > .vs-score{position:absolute;inset:0;min-height:0;margin:0;border:0}
.demo-versus.is-record .vs-race{padding:calc(var(--su)*4.6) calc(var(--su)*4.6) calc(var(--su)*2.6);gap:calc(var(--su)*2.6)}
.demo-versus.is-record .sf-btn,.demo-versus.is-record .vs-head-act,.demo-versus.is-record .vs-again,.demo-versus.is-record .sf-note{display:none!important}
.demo-versus.is-record .vs-task{font-size:calc(var(--su)*6.4)}
.demo-versus.is-record.is-tall .vs-task{font-size:calc(var(--su)*8.4)}
.demo-versus.is-record .sf-eyebrow{font-size:calc(var(--su)*1.4);margin-bottom:calc(var(--su)*1.6)}
.demo-versus.is-record .vs-foot{font-size:calc(var(--su)*1.35)}
.demo-versus.is-record.is-tall .vs-lane{--meta:calc(var(--su)*12)}
.demo-versus.is-record.is-tall .vs-clock{font-size:calc(var(--su)*7)}
.demo-versus.is-record.is-tall .vs-clicks{font-size:calc(var(--su)*2.4)}
.demo-versus.is-record.is-tall .vs-clicks b{font-size:calc(var(--su)*3.8)}
.demo-versus.is-record.is-tall .vs-label{font-size:calc(var(--su)*1.9)}
.demo-versus.is-record.is-tall .vs-ff,.demo-versus.is-record.is-tall .vs-done{font-size:calc(var(--su)*1.9)}
.demo-versus.is-record .vs-score,.demo-versus.is-record .vs-how,.demo-versus.is-record .vs-end{display:grid;align-content:center;padding:calc(var(--su)*6);visibility:hidden;opacity:0}
.demo-versus.is-record .vs-score-in,.demo-versus.is-record .vs-how-in,.demo-versus.is-record .vs-end-in{width:100%;max-width:none}
.demo-versus.is-record .sf-eyebrow{font-size:calc(var(--su)*1.5)}
.demo-versus.is-record .vs-srow{padding:calc(var(--su)*2.8) 0;gap:calc(var(--su)*1.4) calc(var(--su)*3)}
.demo-versus.is-record .vs-sk{font-size:calc(var(--su)*4)}
.demo-versus.is-record .vs-sv{grid-template-columns:calc(var(--su)*16) minmax(0,1fr) calc(var(--su)*12);gap:calc(var(--su)*1.6)}
.demo-versus.is-record .vs-sl{font-size:calc(var(--su)*1.3)}
.demo-versus.is-record .vs-sbar{height:calc(var(--su)*1.1)}
.demo-versus.is-record .vs-sbar b{transition:none;transform:scaleX(calc(var(--w) * var(--g,0)))}
.demo-versus.is-record .vs-snum{font-size:calc(var(--su)*2.6)}
.demo-versus.is-record .vs-stools{font-size:calc(var(--su)*1.25);margin-top:calc(var(--su)*-.8)}
.demo-versus.is-record .vs-sx{font-size:calc(var(--su)*3)}
.demo-versus.is-record .vs-source{font-size:calc(var(--su)*1.3);margin-top:calc(var(--su)*2.4)}
.demo-versus.is-record .vs-how-h{font-size:calc(var(--su)*6);margin-bottom:calc(var(--su)*4)}
.demo-versus.is-record .vs-move{transition:none;opacity:var(--in,0);transform:translateY(calc((1 - var(--in,0)) * var(--su) * 2))}
.demo-versus.is-record .vs-mn{font-size:calc(var(--su)*1.3);margin:calc(var(--su)*2) 0 calc(var(--su)*1)}
.demo-versus.is-record .vs-move h3{font-size:calc(var(--su)*3.4)}
.demo-versus.is-record .vs-ml{font-size:calc(var(--su)*1.7)}
.demo-versus.is-record .vs-back{font-size:calc(var(--su)*17);opacity:var(--end,0);transform:translateY(calc((1 - var(--end,0)) * var(--su) * 3))}
.demo-versus.is-record .vs-end-row{margin-top:calc(var(--su)*6);padding-top:calc(var(--su)*2.4)}
.demo-versus.is-record .vs-end-name{font-size:calc(var(--su)*5)}
.demo-versus.is-record .vs-url-end{font-size:calc(var(--su)*2.2);color:var(--ink)}
/* record, stacked (1:1, 9:16): the score's rows and the how strip go one above the other */
.demo-versus.is-record.is-stacked .vs-srow{grid-template-columns:minmax(0,1fr) auto;gap:calc(var(--su)*1.4)}
.demo-versus.is-record.is-stacked .vs-sk{grid-row:1;grid-column:1}
.demo-versus.is-record.is-stacked .vs-sx{grid-row:1;grid-column:2}
.demo-versus.is-record.is-stacked .vs-sv{grid-column:1 / -1;grid-row:auto}
.demo-versus.is-record.is-stacked .vs-moves{grid-template-columns:minmax(0,1fr);gap:calc(var(--su)*2.6)}
.demo-versus.is-record.is-stacked:not(.is-tall) .vs-move{display:grid;grid-template-columns:44% minmax(0,1fr);grid-template-rows:auto auto 1fr;column-gap:calc(var(--su)*3)}
.demo-versus.is-record.is-stacked:not(.is-tall) .vs-mframe{grid-row:1 / span 3}
.demo-versus.is-record.is-stacked:not(.is-tall) .vs-mn{margin-top:calc(var(--su)*1)}
.demo-versus.is-record.is-stacked:not(.is-tall) .vs-move h3{font-size:calc(var(--su)*3.4)}
.demo-versus.is-record.is-tall .vs-move{display:grid;grid-template-columns:42% minmax(0,1fr);grid-template-rows:auto auto 1fr;column-gap:calc(var(--su)*3)}
.demo-versus.is-record.is-tall .vs-mframe{grid-row:1 / span 3}
.demo-versus.is-record.is-tall .vs-mn{margin-top:0}
.demo-versus.is-record.is-tall .vs-move h3{font-size:calc(var(--su)*4.2)}
.demo-versus.is-record.is-tall .vs-ml{font-size:calc(var(--su)*2.2)}
.demo-versus.is-record.is-tall .vs-sk{font-size:calc(var(--su)*5.6)}
.demo-versus.is-record.is-tall .vs-snum{font-size:calc(var(--su)*3.6)}
.demo-versus.is-record.is-tall .vs-sl{font-size:calc(var(--su)*1.8)}
.demo-versus.is-record.is-tall .vs-sx{font-size:calc(var(--su)*4)}
.demo-versus.is-record.is-tall .vs-back{font-size:calc(var(--su)*19);white-space:normal}
.demo-versus.is-record.is-stacked .vs-end-row{flex-direction:column;align-items:flex-start}

/* ── the old way, in design pixels (880 × 580): a generic tangle of tabs, a dashboard, a sheet and mail ── */
.vs-old{position:relative;display:flex;flex-direction:column;background:var(--ph);font:400 13px/1.35 var(--sans);color:var(--ink);text-align:left;overflow:hidden}
.vs-old svg{width:15px;height:15px;flex:none;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.vs-tabs{flex:none;height:40px;display:flex;align-items:flex-end;gap:2px;padding:0 10px 0 14px;background:var(--page-2)}
.vs-lights{display:flex;gap:7px;align-self:center;margin-right:12px}
.vs-lights i{width:11px;height:11px;border-radius:50%;background:#ec6a5e}.vs-lights i+i{background:#f4bf4f}.vs-lights i+i+i{background:#61c554}
.vs-tab{display:flex;align-items:center;gap:7px;height:32px;padding:0 14px;border-radius:9px 9px 0 0;font:500 12px/1 var(--sans);color:var(--ink-3);white-space:nowrap;max-width:150px;overflow:hidden}
.vs-tab i{width:12px;height:12px;flex:none;border-radius:3px;background:var(--rule)}
.vs-tab.is-more{padding:0 8px}
.vs-tab.is-hover{background:color-mix(in srgb,var(--ph) 50%,transparent)}
.vs-old[data-view="dash"] [data-tab="dash"],.vs-old[data-view="sheet"] [data-tab="sheet"],.vs-old[data-view="mail"] [data-tab="mail"]{background:var(--ph);color:var(--ink)}
[data-tab="dash"] i{background:#8a8378}[data-tab="sheet"] i{background:#6f8a6a}[data-tab="mail"] i{background:#a1735c}
.vs-addr{flex:none;height:36px;display:flex;align-items:center;gap:10px;padding:0 14px;border-bottom:1px solid var(--line);color:var(--ink-3)}
.vs-url{flex:1;height:24px;display:flex;align-items:center;padding:0 12px;border-radius:6px;background:var(--page);font:400 12px/1 var(--sans);color:var(--ink-2)}
.vs-url span{display:none}
.vs-old[data-view="dash"] [data-u="dash"],.vs-old[data-view="sheet"] [data-u="sheet"],.vs-old[data-view="mail"] [data-u="mail"]{display:inline}
.vs-views{position:relative;flex:1;min-height:0}
.vs-v{position:absolute;inset:0;display:none}
.vs-old[data-view="dash"] .vs-dash,.vs-old[data-view="sheet"] .vs-sheet,.vs-old[data-view="mail"] .vs-mail{display:flex}
/* dashboard */
.vs-dash{flex-direction:column;gap:18px;padding:20px 22px}
.vs-dash-bar{display:flex;align-items:center;gap:8px}.vs-dash-bar b{margin-right:auto;font:600 16px/1 var(--sans)}
.vs-chip{padding:6px 10px;border-radius:6px;box-shadow:inset 0 0 0 1px var(--rule);font-weight:500;color:var(--ink-2);font-size:12px}
.vs-tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.vs-tile{display:grid;gap:8px;padding:14px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line)}
.vs-tile small{color:var(--ink-3);font-size:12px}
.vs-tile b{justify-self:start;padding:1px 3px;margin:-1px -3px;border-radius:3px;font:600 24px/1.1 var(--sans);letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.vs-tile b.is-sel{background:#b9d3f3}
.vs-tile i{height:5px;width:var(--w);border-radius:3px;background:var(--rule)}
.vs-chart{flex:1;display:flex;align-items:flex-end;gap:14px;padding:16px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line)}
.vs-chart i{flex:1;height:calc(var(--h) * 100%);border-radius:4px 4px 0 0;background:var(--page-2)}
/* spreadsheet */
.vs-sheet{flex-direction:column}
.vs-menu{flex:none;display:flex;gap:2px;padding:6px 10px;border-bottom:1px solid var(--line);color:var(--ink-2);font-weight:500}
.vs-menu span{padding:5px 9px;border-radius:5px}
.vs-menu span.is-hover{background:var(--page-2)}
.vs-fx{flex:none;height:30px;display:flex;align-items:center;gap:12px;padding:0 12px;border-bottom:1px solid var(--line);font:400 12.5px/1 var(--sans)}
.vs-fx i{font:italic 500 12px/1 var(--serif);color:var(--ink-3)}
.vs-grid{flex:1;min-height:0;display:grid;grid-template-columns:42px 1.5fr 1fr 1fr 1fr 1fr;grid-auto-rows:30px;overflow:hidden;font-size:12.5px}
.vs-grid > span{display:flex;align-items:center;padding:0 9px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);white-space:nowrap;font-variant-numeric:tabular-nums}
.vs-grid .h{justify-content:center;background:var(--page);color:var(--ink-3);font-size:11px}
.vs-grid .hd{font-weight:600}
.vs-grid .c{justify-content:flex-end}
.vs-grid .c.is-sel{box-shadow:inset 0 0 0 2px #3d7bd8;background:color-mix(in srgb,#b9d3f3 30%,transparent)}
.vs-dd{--in:0;position:absolute;z-index:4;left:12px;top:36px;width:190px;padding:5px;display:grid;border-radius:8px;background:var(--ph);box-shadow:0 0 0 1px var(--line),0 16px 34px -14px rgba(25,24,22,.45);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * -4px));pointer-events:none}
.vs-dd span{padding:7px 10px;border-radius:5px;color:var(--ink-2)}
.vs-dd span.is-hover{background:#3d7bd8;color:#fff}
/* mail */
.vs-mail{flex-direction:row}
.vs-mlist{flex:none;width:230px;display:flex;flex-direction:column;gap:2px;padding:14px 10px;border-right:1px solid var(--line);background:var(--page)}
.vs-compose{align-self:flex-start;margin:0 4px 12px;padding:9px 16px;border-radius:8px;background:var(--ph);box-shadow:0 0 0 1px var(--line),0 2px 4px -2px rgba(25,24,22,.2);font-weight:600}
.vs-compose.is-hover{background:var(--page-2)}
.vs-mrow{display:grid;gap:7px;padding:11px 10px;border-radius:7px}
.vs-mrow b{height:7px;width:46%;border-radius:4px;background:var(--rule)}.vs-mrow i{height:6px;width:var(--w);border-radius:3px;background:var(--line)}
.vs-mail-pane{position:relative;flex:1;min-width:0;padding:18px}
.vs-draft{--in:0;height:100%;display:flex;flex-direction:column;gap:2px;padding:4px 18px 16px;border-radius:12px;box-shadow:0 0 0 1px var(--line),0 18px 40px -24px rgba(25,24,22,.4);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 10px))}
.vs-mf{display:flex;align-items:center;gap:14px;margin:0;height:42px;border-bottom:1px solid var(--line)}
.vs-mf small{width:56px;color:var(--ink-3);font-size:12px}
.vs-mf span{flex:1;min-height:18px;font-weight:500}
.vs-mf span.is-caret::after{content:"";display:inline-block;width:1.5px;height:15px;margin-left:1px;vertical-align:-3px;background:var(--ink)}
.vs-mbody{flex:1;padding:16px 0}
.vs-att{--in:0;display:flex;align-items:center;gap:10px;align-self:flex-start;padding:9px 12px;border-radius:8px;box-shadow:inset 0 0 0 1px var(--line);opacity:var(--in);margin-bottom:12px}
.vs-att i{width:16px;height:20px;border-radius:3px;background:#6f8a6a}
.vs-att span{font-weight:500}.vs-att small{color:var(--ink-3)}
.vs-mfoot{display:flex;flex-direction:row-reverse;justify-content:flex-end;gap:8px}
.vs-old .vs-btn,.vs-app .vs-btn{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 14px;border-radius:7px;background:var(--ph);box-shadow:inset 0 0 0 1px var(--rule);font-weight:500;color:var(--ink);white-space:nowrap}
.vs-old .vs-btn.is-primary,.vs-app .vs-btn.is-primary{background:var(--ink);color:var(--page);box-shadow:none}
.vs-old .vs-btn.is-hover,.vs-app .vs-btn.is-hover{background:var(--page)}
.vs-old .vs-btn.is-primary.is-hover,.vs-app .vs-btn.is-primary.is-hover{background:#000}
.vs-old .is-press,.vs-app .is-press{transform:scale(.96)}
/* the waits */
.vs-scrim{--in:0;position:absolute;inset:0;z-index:5;background:rgba(25,24,22,.2);opacity:var(--in);pointer-events:none}
.vs-wait{--in:0;--a:0;position:absolute;z-index:6;left:50%;top:50%;width:300px;margin:-70px 0 0 -150px;padding:26px 22px 22px;display:grid;justify-items:center;gap:8px;border-radius:14px;background:var(--ph);
  box-shadow:0 0 0 1px var(--line),0 30px 60px -24px rgba(25,24,22,.5);opacity:var(--in);transform:scale(calc(.97 + .03 * var(--in)))}
.vs-spin{width:30px;height:30px;margin-bottom:8px;border-radius:50%;border:3px solid var(--page-2);border-top-color:var(--ink-2);transform:rotate(calc(var(--a) * 1deg))}
.vs-wait b{font:600 15px/1.2 var(--sans)}.vs-wait small{color:var(--ink-3)}
.vs-pick{--in:0;position:absolute;z-index:6;left:50%;top:50%;width:380px;margin:-130px 0 0 -190px;padding:18px;display:grid;gap:4px;border-radius:12px;background:var(--ph);
  box-shadow:0 0 0 1px var(--line),0 30px 60px -24px rgba(25,24,22,.5);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 10px))}
.vs-pick b{margin-bottom:8px;font:600 15px/1 var(--sans)}
.vs-file{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:7px;color:var(--ink-2)}
.vs-file i{width:14px;height:17px;border-radius:2px;background:var(--rule)}
.vs-file.is-hover{background:var(--page)}
.vs-file.is-on{background:#3d7bd8;color:#fff}
.vs-pick-ok{justify-self:end;margin-top:10px}
.vs-sent{--in:0;position:absolute;z-index:7;left:50%;bottom:22px;display:flex;align-items:center;gap:9px;padding:11px 16px 11px 13px;border-radius:10px;background:var(--ink);color:var(--page);font-weight:500;opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 12px))}

/* ── the placeholder product, in design pixels (880 × 580 with the app title bar) ── */
.vs-app{--open:0;--g:0;position:relative;display:grid;grid-template-columns:58px minmax(0,1fr);background:var(--ph);font:400 13px/1.35 var(--sans);color:var(--ink);text-align:left;overflow:hidden}
.vs-app svg{width:16px;height:16px;flex:none;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.vs-rail{display:flex;flex-direction:column;align-items:center;gap:6px;padding:14px 0;background:var(--page);border-right:1px solid var(--line);color:var(--ink-3)}
.vs-logo{width:26px;height:26px;margin-bottom:12px;border-radius:7px;background:var(--ink)}
.vs-rail i{display:grid;place-items:center;width:36px;height:36px;border-radius:8px}
.vs-rail i.is-on{background:var(--ph);color:var(--ink);box-shadow:0 0 0 1px var(--line)}
.vs-main{position:relative;display:flex;flex-direction:column;min-width:0}
.vs-bar{flex:none;height:56px;display:flex;align-items:center;gap:12px;padding:0 22px;border-bottom:1px solid var(--line)}
.vs-bar h4{margin:0 auto 0 0;font:600 17px/1 var(--sans);letter-spacing:-.01em}
.vs-search{display:flex;align-items:center;gap:8px;width:190px;height:32px;padding:0 10px;border-radius:7px;box-shadow:inset 0 0 0 1px var(--line);color:var(--ink-3)}
.vs-list{display:grid;gap:4px;padding:16px 16px}
.vs-row{display:flex;align-items:center;gap:14px;padding:12px 12px;border-radius:10px}
.vs-row > span:nth-child(2){display:grid;gap:6px}
.vs-row b{font-weight:600}.vs-row small{color:var(--ink-3);font-size:12px}
.vs-row i{display:block;height:8px;width:var(--w);border-radius:4px;background:var(--rule)}
.vs-row small i{height:6px;background:var(--line)}
.vs-ic{width:36px;height:36px;flex:none;border-radius:9px;background:var(--page-2)}
.vs-row[data-tour="report"] .vs-ic{background:var(--ink-2)}
.vs-row em{margin-left:auto;padding:4px 8px;border-radius:5px;background:var(--page);box-shadow:inset 0 0 0 1px var(--line);font:500 11.5px/1 var(--sans);font-style:normal;color:var(--ink-2)}
.vs-row.is-hover{background:var(--page)}
.vs-panel{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;background:var(--ph);opacity:min(1,calc(var(--open) * 3));transform:translateX(calc((1 - var(--open)) * 36px));pointer-events:none}
.vs-panel-bar{flex:none;height:56px;display:flex;align-items:center;gap:10px;padding:0 18px 0 16px;border-bottom:1px solid var(--line)}
.vs-panel-bar > b{margin-right:auto;font:600 16px/1 var(--sans)}
.vs-panel-bar > svg{color:var(--ink-3)}
.vs-status{font-size:12px;color:var(--ink-3);margin-right:6px}
.vs-panel.is-fresh .vs-status{color:#4f7a4a}
.vs-panel-body{flex:1;display:flex;flex-direction:column;gap:16px;padding:20px 22px}
.vs-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.vs-kpi{display:grid;gap:6px;padding:14px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line)}
.vs-kpi small{color:var(--ink-3);font-size:12px}
.vs-kpi b{font:600 26px/1.1 var(--sans);letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.vs-kpi em{font:500 12px/1 var(--sans);font-style:normal;color:var(--ink-3);opacity:var(--g)}
.vs-kpi em.vs-up{color:#4f7a4a}
.vs-bars{flex:1;display:flex;align-items:flex-end;gap:14px;padding:16px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line)}
.vs-bars i{flex:1;height:calc(var(--h) * var(--g) * 100%);border-radius:4px 4px 0 0;background:var(--rule)}
.vs-bars i:last-child{background:var(--ink-2)}
.vs-pop{--in:0;position:absolute;z-index:6;right:16px;top:62px;width:320px;padding:16px;display:grid;gap:12px;border-radius:12px;background:var(--ph);
  box-shadow:0 0 0 1px var(--line),0 24px 50px -22px rgba(25,24,22,.5);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * -8px));pointer-events:none}
.vs-pop > b{font:600 15px/1 var(--sans)}
.vs-to{display:flex;align-items:center;justify-content:space-between;padding:8px 10px;border-radius:8px;box-shadow:inset 0 0 0 1px var(--rule)}
.vs-who{display:flex;align-items:center;gap:8px;font-weight:500}.vs-who .ph{width:22px}
.vs-to small{color:var(--ink-3);font-size:12px}
.vs-pop-go{justify-self:end}
.vs-toast{--in:0;position:absolute;z-index:7;left:50%;bottom:22px;display:flex;align-items:center;gap:9px;padding:11px 16px 11px 13px;border-radius:10px;background:var(--ink);color:var(--page);font-weight:500;
  box-shadow:0 16px 34px -16px rgba(25,24,22,.6);opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 14px))}
.vs-toast svg{color:var(--page)}

/* phones: the race grows taller than the screen so each window can take the full width */
@media (max-width:640px){
  .demo-versus.is-stacked:not(.is-record) .vs-race{min-height:0}
  .demo-versus.is-stacked:not(.is-record) .vs-lanes{grid-template-rows:none}
  .demo-versus.is-stacked:not(.is-record) .vs-lane{height:calc((100vw - 2 * var(--gutter)) / 1.5172 + var(--meta))}
}
.demo-versus.is-record.is-stacked:not(.is-tall) .vs-back{font-size:calc(var(--su)*12.5)}
